/**
 * The typed tables of the identityDevice model, generated by IFC Data from the model. Do not edit: change the model and run `bun tools/typed.ts --write`.
 *
 * Device identities: endpoints, servers and things
 *
 * @module
 */
import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** What a device runs */
export interface PlatformRow {
  /** The code other tables point to: a short word that does not change */
  readonly code: string;
  /** What a person is shown for the code */
  readonly label: string;
  /** What the code means, where the label is not enough */
  readonly description: string | null;
}

/** What an insert into platform takes: what the database fills may be left out. */
export interface PlatformInsert {
  readonly code: string;
  readonly label: string;
  readonly description?: string | null;
}

/** The key of a row of platform. */
export type PlatformKey = { readonly code: string };

/** What a device runs */
export const platform = defineTable<PlatformRow, PlatformInsert, "platform">({
  alias: "platform",
  name: "platform",
  columns: {
    code: "code",
    label: "label",
    description: "description",
  },
  primaryKey: ["code"],
});

/** Hardware that has an identity and an owner: an endpoint, a server or a thing */
export interface DeviceRow {
  /** The principal the device is */
  readonly principalId: string;
  /** What kind of device it is */
  readonly deviceKind: "laptop" | "phone" | "tablet" | "server" | "iot" | "other";
  /** What it runs */
  readonly platformCode: string;
  /** A hash of its serial number or hardware identifier */
  readonly hardwareHash: string;
  /** What it is called */
  readonly label: string | null;
  /** How far it is managed */
  readonly managementState: "unmanaged" | "registered" | "managed" | "retired";
  /** Whose it is */
  readonly ownership: "corporate" | "personal" | "shared";
  /** When it was enrolled */
  readonly enrolledAt: Timestamp;
  /** When it was last seen */
  readonly lastSeenAt: Timestamp | null;
  /** Until when it is trusted without a fresh attestation */
  readonly trustedUntil: Timestamp | null;
}

/** What an insert into device takes: what the database fills may be left out. */
export interface DeviceInsert {
  readonly principalId: string;
  readonly deviceKind: "laptop" | "phone" | "tablet" | "server" | "iot" | "other";
  readonly platformCode: string;
  readonly hardwareHash: string;
  readonly label?: string | null;
  readonly managementState: "unmanaged" | "registered" | "managed" | "retired";
  readonly ownership: "corporate" | "personal" | "shared";
  readonly enrolledAt: Timestamp;
  readonly lastSeenAt?: Timestamp | null;
  readonly trustedUntil?: Timestamp | null;
}

/** The key of a row of device. */
export type DeviceKey = { readonly principalId: string };

/** Hardware that has an identity and an owner: an endpoint, a server or a thing */
export const device = defineTable<DeviceRow, DeviceInsert, "device">({
  alias: "device",
  name: "device",
  columns: {
    principalId: "principal_id",
    deviceKind: "device_kind",
    platformCode: "platform_code",
    hardwareHash: "hardware_hash",
    label: "label",
    managementState: "management_state",
    ownership: "ownership",
    enrolledAt: "enrolled_at",
    lastSeenAt: "last_seen_at",
    trustedUntil: "trusted_until",
  },
  primaryKey: ["principalId"],
  foreignKeys: [
    { columns: ["principalId"], references: "principal", referencesColumns: ["principalId"] },
    { columns: ["platformCode"], references: "platform", referencesColumns: ["code"] },
  ],
});

/** What a device proved about itself, and how it was judged */
export interface DeviceAttestationRow {
  /** What identifies the attestation, made by the application */
  readonly deviceAttestationId: string;
  /** What was proved */
  readonly kind: "tpm" | "platform_attestation" | "webauthn_attestation" | "spiffe_node" | "cloud_instance" | "mdm_enrollment";
  /** A hash of the evidence; the evidence is kept by the verifier */
  readonly evidenceHash: string;
  /** What judged it */
  readonly verifier: string;
  /** How it was judged */
  readonly result: "passed" | "failed" | "unknown";
  /** When it was judged */
  readonly attestedAt: Timestamp;
  /** When it stops counting */
  readonly expiresAt: Timestamp;
  /** A hash of the nonce the device was challenged with */
  readonly nonceHash: string;
  /** The device */
  readonly devicePrincipalId: string;
}

/** What an insert into device_attestation takes: what the database fills may be left out. */
export interface DeviceAttestationInsert {
  readonly deviceAttestationId: string;
  readonly kind: "tpm" | "platform_attestation" | "webauthn_attestation" | "spiffe_node" | "cloud_instance" | "mdm_enrollment";
  readonly evidenceHash: string;
  readonly verifier: string;
  readonly result: "passed" | "failed" | "unknown";
  readonly attestedAt: Timestamp;
  readonly expiresAt: Timestamp;
  readonly nonceHash: string;
  readonly devicePrincipalId: string;
}

/** The key of a row of device_attestation. */
export type DeviceAttestationKey = { readonly deviceAttestationId: string };

/** What a device proved about itself, and how it was judged */
export const deviceAttestation = defineTable<DeviceAttestationRow, DeviceAttestationInsert, "deviceAttestation">({
  alias: "deviceAttestation",
  name: "device_attestation",
  columns: {
    deviceAttestationId: "device_attestation_id",
    kind: "kind",
    evidenceHash: "evidence_hash",
    verifier: "verifier",
    result: "result",
    attestedAt: "attested_at",
    expiresAt: "expires_at",
    nonceHash: "nonce_hash",
    devicePrincipalId: "device_principal_id",
  },
  primaryKey: ["deviceAttestationId"],
  foreignKeys: [
    { columns: ["devicePrincipalId"], references: "device", referencesColumns: ["principalId"] },
  ],
});

/** How a device was doing when it last reported; after its time is up it reads as unknown, never as compliant */
export interface DevicePostureRow {
  /** What identifies the report, made by the application */
  readonly devicePostureId: string;
  /** What reported it */
  readonly source: "mdm" | "edr" | "agent" | "manual";
  /** Whether the device meets what is asked of it */
  readonly compliance: "compliant" | "noncompliant" | "unknown";
  /** The version of what it runs */
  readonly osVersion: string | null;
  /** Whether its storage is encrypted */
  readonly diskEncrypted: boolean | null;
  /** Whether it locks its screen */
  readonly screenLock: boolean | null;
  /** Whether its firewall is on */
  readonly firewall: boolean | null;
  /** Whether it has been broken out of its platform's protections */
  readonly jailbroken: boolean | null;
  /** Whether endpoint detection is running */
  readonly edrActive: boolean | null;
  /** How many days old its latest patch is */
  readonly patchAgeDays: number | null;
  /** A score from its reporter */
  readonly riskScore: number | null;
  /** What else was reported */
  readonly details: unknown | null;
  /** When it was reported */
  readonly reportedAt: Timestamp;
  /** When the report stops counting */
  readonly validUntil: Timestamp;
  /** The device */
  readonly devicePrincipalId: string;
}

/** What an insert into device_posture takes: what the database fills may be left out. */
export interface DevicePostureInsert {
  readonly devicePostureId: string;
  readonly source: "mdm" | "edr" | "agent" | "manual";
  readonly compliance: "compliant" | "noncompliant" | "unknown";
  readonly osVersion?: string | null;
  readonly diskEncrypted?: boolean | null;
  readonly screenLock?: boolean | null;
  readonly firewall?: boolean | null;
  readonly jailbroken?: boolean | null;
  readonly edrActive?: boolean | null;
  readonly patchAgeDays?: number | null;
  readonly riskScore?: number | null;
  readonly details?: unknown | null;
  readonly reportedAt: Timestamp;
  readonly validUntil: Timestamp;
  readonly devicePrincipalId: string;
}

/** The key of a row of device_posture. */
export type DevicePostureKey = { readonly devicePostureId: string };

/** How a device was doing when it last reported; after its time is up it reads as unknown, never as compliant */
export const devicePosture = defineTable<DevicePostureRow, DevicePostureInsert, "devicePosture">({
  alias: "devicePosture",
  name: "device_posture",
  columns: {
    devicePostureId: "device_posture_id",
    source: "source",
    compliance: "compliance",
    osVersion: "os_version",
    diskEncrypted: "disk_encrypted",
    screenLock: "screen_lock",
    firewall: "firewall",
    jailbroken: "jailbroken",
    edrActive: "edr_active",
    patchAgeDays: "patch_age_days",
    riskScore: "risk_score",
    details: "details",
    reportedAt: "reported_at",
    validUntil: "valid_until",
    devicePrincipalId: "device_principal_id",
  },
  primaryKey: ["devicePostureId"],
  foreignKeys: [
    { columns: ["devicePrincipalId"], references: "device", referencesColumns: ["principalId"] },
  ],
});

/** A session of a person that is on a device, so that a decision about the person can use the device's posture */
export interface DeviceSessionRow {
  /** The device */
  readonly devicePrincipalId: string;
  /** The session */
  readonly sessionLoginSessionSessionId: string;
  /** When the session was bound to the device */
  readonly boundAt: Timestamp;
}

/** What an insert into device_session takes: what the database fills may be left out. */
export interface DeviceSessionInsert {
  readonly devicePrincipalId: string;
  readonly sessionLoginSessionSessionId: string;
  readonly boundAt: Timestamp;
}

/** The key of a row of device_session. */
export type DeviceSessionKey = { readonly devicePrincipalId: string; readonly sessionLoginSessionSessionId: string };

/** A session of a person that is on a device, so that a decision about the person can use the device's posture */
export const deviceSession = defineTable<DeviceSessionRow, DeviceSessionInsert, "deviceSession">({
  alias: "deviceSession",
  name: "device_session",
  columns: {
    devicePrincipalId: "device_principal_id",
    sessionLoginSessionSessionId: "session_login_session_session_id",
    boundAt: "bound_at",
  },
  primaryKey: ["devicePrincipalId", "sessionLoginSessionSessionId"],
  foreignKeys: [
    { columns: ["devicePrincipalId"], references: "device", referencesColumns: ["principalId"] },
    { columns: ["sessionLoginSessionSessionId"], references: "loginSession", referencesColumns: ["sessionId"] },
  ],
});
